def linear_create_issue(team_id, title, description_md=None, assignee_id=None, state_id=None, priority=None, estimate=None, labels=None, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0204000" if __import__("os").path.isdir("./environment_mix/0204000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    req_status = "ok"
    req_error = None

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, error=None):
        # Best-effort request logging if a log collection exists.
        for fname in ("request_logs.json", "usage.json", "audit_logs.json", "requests.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                entry = {
                    "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
                    "endpoint": "linear_create_issue",
                    "status": status,
                    "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
                    "latency_ms": int((time.time() - _t0) * 1000),
                    "timestamp": _now(),
                }
                logs.append(entry)
                _save(fname, logs)
                break

    # ---- Validate inputs (types/patterns/enums/ranges) ----
    try:
        if not isinstance(team_id, str):
            req_status, req_error = "error", {"code": "VALIDATION_ERROR"}
            _log(req_status, req_error)
            return _err("VALIDATION_ERROR", "team_id must be a string")
        if not re.match(r"^team_[0-9A-HJKMNP-TV-Z]{17,}$", team_id):
            req_status, req_error = "error", {"code": "VALIDATION_ERROR"}
            _log(req_status, req_error)
            return _err("VALIDATION_ERROR", "team_id is not a valid ULID", field="team_id")

        if not isinstance(title, str) or len(title) < 1:
            req_status, req_error = "error", {"code": "VALIDATION_ERROR"}
            _log(req_status, req_error)
            return _err("VALIDATION_ERROR", "title must be a non-empty string", field="title")

        if description_md is not None and not isinstance(description_md, str):
            req_status, req_error = "error", {"code": "VALIDATION_ERROR"}
            _log(req_status, req_error)
            return _err("VALIDATION_ERROR", "description_md must be a string", field="description_md")

        if assignee_id is not None:
            if not isinstance(assignee_id, str) or not re.match(r"^usr_[0-9A-HJKMNP-TV-Z]{17,}$", assignee_id):
                req_status, req_error = "error", {"code": "VALIDATION_ERROR"}
                _log(req_status, req_error)
                return _err("VALIDATION_ERROR", "assignee_id is not a valid ULID", field="assignee_id")

        if state_id is not None:
            if not isinstance(state_id, str) or not re.match(r"^state_[0-9A-HJKMNP-TV-Z]{17,}$", state_id):
                req_status, req_error = "error", {"code": "VALIDATION_ERROR"}
                _log(req_status, req_error)
                return _err("VALIDATION_ERROR", "state_id is not a valid ULID", field="state_id")

        if priority is not None:
            if not isinstance(priority, int) or priority not in (1, 2, 3, 4):
                req_status, req_error = "error", {"code": "VALIDATION_ERROR"}
                _log(req_status, req_error)
                return _err("VALIDATION_ERROR", "priority must be one of 1,2,3,4", field="priority")

        if estimate is not None:
            if not isinstance(estimate, (int, float)):
                req_status, req_error = "error", {"code": "VALIDATION_ERROR"}
                _log(req_status, req_error)
                return _err("VALIDATION_ERROR", "estimate must be a number", field="estimate")
            if estimate < 0:
                req_status, req_error = "error", {"code": "VALIDATION_ERROR"}
                _log(req_status, req_error)
                return _err("VALIDATION_ERROR", "estimate must be >= 0", field="estimate")

        if labels is None:
            labels = []
        else:
            if not isinstance(labels, list):
                req_status, req_error = "error", {"code": "VALIDATION_ERROR"}
                _log(req_status, req_error)
                return _err("VALIDATION_ERROR", "labels must be an array of strings", field="labels")
            for i, lab in enumerate(labels):
                if not isinstance(lab, str):
                    req_status, req_error = "error", {"code": "VALIDATION_ERROR"}
                    _log(req_status, req_error)
                    return _err("VALIDATION_ERROR", "labels must be an array of strings", field="labels", index=i)
                if lab.strip() == "":
                    req_status, req_error = "error", {"code": "VALIDATION_ERROR"}
                    _log(req_status, req_error)
                    return _err("VALIDATION_ERROR", "labels must not contain empty strings", field="labels", index=i)
            # distinct
            norm = [s.strip() for s in labels]
            if len(set(norm)) != len(norm):
                req_status, req_error = "error", {"code": "VALIDATION_ERROR"}
                _log(req_status, req_error)
                return _err("VALIDATION_ERROR", "labels must be distinct", field="labels")
            labels = norm

        # ---- Load referenced collections ----
        teams = _load("teams.json")
        users = _load("users.json")
        states = _load("workflow_states.json")
        issues = _load("issues.json")

        team = next((t for t in teams if t.get("id") == team_id), None)
        if not team:
            req_status, req_error = "error", {"code": "NOT_FOUND"}
            _log(req_status, req_error)
            return _err("NOT_FOUND", "team_id not found", field="team_id")
        if team.get("status") == "archived":
            req_status, req_error = "error", {"code": "CONFLICT"}
            _log(req_status, req_error)
            return _err("CONFLICT", "Cannot create issues in an archived team", team_id=team_id)

        # Determine creator (authenticated ambient identity): service identity user
        creator = next((u for u in users if u.get("is_service_identity") is True and u.get("status") == "active"), None)
        if not creator:
            req_status, req_error = "error", {"code": "UNAUTHORIZED"}
            _log(req_status, req_error)
            return _err("UNAUTHORIZED", "No authenticated identity available")

        if assignee_id is not None:
            assignee = next((u for u in users if u.get("id") == assignee_id), None)
            if not assignee:
                req_status, req_error = "error", {"code": "NOT_FOUND"}
                _log(req_status, req_error)
                return _err("NOT_FOUND", "assignee_id not found", field="assignee_id")
            if assignee.get("status") != "active":
                req_status, req_error = "error", {"code": "CONFLICT"}
                _log(req_status, req_error)
                return _err("CONFLICT", "assignee must be active", assignee_id=assignee_id)

        # Resolve state
        state = None
        if state_id is not None:
            state = next((s for s in states if s.get("id") == state_id), None)
            if not state:
                req_status, req_error = "error", {"code": "NOT_FOUND"}
                _log(req_status, req_error)
                return _err("NOT_FOUND", "state_id not found", field="state_id")
            if state.get("team_id") != team_id:
                req_status, req_error = "error", {"code": "VALIDATION_ERROR"}
                _log(req_status, req_error)
                return _err("VALIDATION_ERROR", "state_id must belong to the same team as team_id", field="state_id")
            if state.get("status") == "hidden":
                req_status, req_error = "error", {"code": "CONFLICT"}
                _log(req_status, req_error)
                return _err("CONFLICT", "Cannot select a hidden workflow state for a new issue", state_id=state_id)
        else:
            # default state for this team
            state = next((s for s in states if s.get("team_id") == team_id and s.get("is_default") is True and s.get("status") == "active"), None)
            if not state:
                req_status, req_error = "error", {"code": "NOT_FOUND"}
                _log(req_status, req_error)
                return _err("NOT_FOUND", "No default active workflow state found for team", team_id=team_id)

        # ---- Allocate per-team number atomically (best-effort file lock) ----
        lock_path = os.path.join(_DB, ".issues.lock")
        lock_fd = None
        try:
            lock_fd = os.open(lock_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        except FileExistsError:
            # contention: treat as rate limit / conflict
            req_status, req_error = "error", {"code": "CONFLICT"}
            _log(req_status, req_error)
            return _err("CONFLICT", "Issue creation is busy; please retry")
        except Exception:
            req_status, req_error = "error", {"code": "CONFLICT"}
            _log(req_status, req_error)
            return _err("CONFLICT", "Unable to acquire allocation lock")

        try:
            # reload issues inside lock
            issues = _load("issues.json")
            max_num = 0
            for it in issues:
                if it.get("team_id") == team_id and isinstance(it.get("number"), int):
                    if it["number"] > max_num:
                        max_num = it["number"]
            next_num = max_num + 1
            if next_num < 1:
                next_num = 1
            identifier = f"{team.get('key')}-{next_num}"

            # enforce unique(identifier) and unique(team_id, number)
            if any(it.get("team_id") == team_id and it.get("number") == next_num for it in issues):
                req_status, req_error = "error", {"code": "CONFLICT"}
                _log(req_status, req_error)
                return _err("CONFLICT", "Issue number conflict; please retry")
            if any(it.get("identifier") == identifier for it in issues):
                req_status, req_error = "error", {"code": "CONFLICT"}
                _log(req_status, req_error)
                return _err("CONFLICT", "Issue identifier conflict; please retry")

            # generate ULID-like id (not real ULID, but matches required charset/prefix)
            alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
            def _rand_ulid(n=20):
                return "".join(random.choice(alphabet) for _ in range(n))
            new_id = f"iss_{_rand_ulid(20)}"
            while any(it.get("id") == new_id for it in issues):
                new_id = f"iss_{_rand_ulid(20)}"

            # url unique
            url = f"https://linear.app/{team.get('key','team')}/issue/{identifier}"
            if any(it.get("url") == url for it in issues):
                # vary with id
                url = f"https://linear.app/{team.get('key','team')}/issue/{identifier}?i={new_id}"
                if any(it.get("url") == url for it in issues):
                    req_status, req_error = "error", {"code": "CONFLICT"}
                    _log(req_status, req_error)
                    return _err("CONFLICT", "Issue URL conflict; please retry")

            now = _now()
            row = {
                "id": new_id,
                "team_id": team_id,
                "identifier": identifier,
                "number": next_num,
                "title": title,
                "description_md": description_md,
                "assignee_id": assignee_id,
                "creator_id": creator.get("id"),
                "state_id": state.get("id"),
                "priority": priority,
                "estimate": float(estimate) if isinstance(estimate, (int, float)) else None,
                "labels": labels,
                "url": url,
                "status": "open",
                "last_commented_at": None,
                "created_at": now,
                "updated_at": now,
            }

            issues.append(row)
            _save("issues.json", issues)

        finally:
            try:
                if lock_fd is not None:
                    os.close(lock_fd)
                if os.path.exists(lock_path):
                    os.remove(lock_path)
            except Exception:
                pass

        _log("ok", None)
        return {"issue": row}

    except Exception as e:
        req_status, req_error = "error", {"code": "CONFLICT"}
        _log(req_status, req_error)
        return _err("CONFLICT", "Unexpected error", detail=str(e))

def linear_update_issue(issue_id, title=None, description_md=None, assignee_id=None, state_id=None, priority=None, estimate=None, labels=None, status=None, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0204000" if __import__("os").path.isdir("./environment_mix/0204000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "linear_update_issue"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, error_code=None, credential_used=None):
        # Observable dynamics: record to request_logs.json if present, else create it.
        req = _load("request_logs.json")
        if not isinstance(req, list):
            req = []
        req.append({
            "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save("request_logs.json", req)

    try:
        # Validate issue_id
        if not isinstance(issue_id, str) or not re.match(r"^iss_[0-9A-HJKMNP-TV-Z]{17,}$", issue_id):
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid issue_id format.", field="issue_id")

        # Validate provided fields
        if title is not None and (not isinstance(title, str) or len(title) < 1):
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "title must be a non-empty string.", field="title")

        if description_md is not None and not isinstance(description_md, str):
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "description_md must be a string.", field="description_md")

        if assignee_id is not None:
            if not isinstance(assignee_id, str) or not re.match(r"^usr_[0-9A-HJKMNP-TV-Z]{17,}$", assignee_id):
                _append_request_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid assignee_id format.", field="assignee_id")

        if state_id is not None:
            if not isinstance(state_id, str) or not re.match(r"^state_[0-9A-HJKMNP-TV-Z]{17,}$", state_id):
                _append_request_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid state_id format.", field="state_id")

        if priority is not None:
            if not isinstance(priority, int) or priority not in (1, 2, 3, 4):
                _append_request_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "priority must be one of 1, 2, 3, 4.", field="priority")

        if estimate is not None:
            if not isinstance(estimate, (int, float)):
                _append_request_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "estimate must be a number.", field="estimate")
            if estimate < 0:
                _append_request_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "estimate must be >= 0.", field="estimate")

        if labels is not None:
            if not isinstance(labels, list) or any(not isinstance(x, str) for x in labels):
                _append_request_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "labels must be an array of strings.", field="labels")
            cleaned = []
            seen = set()
            for x in labels:
                s = x.strip()
                if not s:
                    _append_request_log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "labels must contain non-empty strings.", field="labels")
                if s in seen:
                    _append_request_log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "labels must be distinct.", field="labels")
                seen.add(s)
                cleaned.append(s)
            labels = cleaned

        if status is not None:
            if not isinstance(status, str) or status not in ("open", "closed", "canceled", "deleted"):
                _append_request_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "status must be one of open/closed/canceled/deleted.", field="status")

        issues = _load("issues.json")
        if not isinstance(issues, list):
            issues = []

        idx = None
        issue = None
        for i, it in enumerate(issues):
            if isinstance(it, dict) and it.get("id") == issue_id:
                idx = i
                issue = it
                break

        if issue is None:
            _append_request_log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Issue not found.", issue_id=issue_id)

        # Reference validations
        if assignee_id is not None:
            users = _load("users.json")
            if not isinstance(users, list):
                users = []
            if not any(u.get("id") == assignee_id for u in users if isinstance(u, dict)):
                _append_request_log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "assignee_id does not reference an existing user.", field="assignee_id", assignee_id=assignee_id)

        # Workflow state consistency when updating state_id
        if state_id is not None:
            wfs = _load("workflow_states.json")
            if not isinstance(wfs, list):
                wfs = []
            st = next((s for s in wfs if isinstance(s, dict) and s.get("id") == state_id), None)
            if st is None:
                _append_request_log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "state_id does not reference an existing workflow state.", field="state_id", state_id=state_id)
            if st.get("team_id") != issue.get("team_id"):
                _append_request_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "workflow_states.team_id must match issue.team_id when updating state_id.", rule="state_team_must_match_issue_team")

        # Lifecycle transition validation for issues.status
        if status is not None:
            current = issue.get("status")
            transitions = {
                "open": ["closed", "canceled", "deleted"],
                "closed": ["open", "deleted"],
                "canceled": ["open", "deleted"],
                "deleted": [],
            }
            if current not in transitions:
                _append_request_log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Issue has invalid current status in datastore.", current_status=current)
            if status != current and status not in transitions[current]:
                _append_request_log("error", "INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", f"Invalid status transition {current} -> {status}.", from_status=current, to_status=status)

        # Apply updates (only allowed fields)
        changed = False
        def _set(field, value):
            nonlocal changed
            if value is None:
                return
            if issue.get(field) != value:
                issue[field] = value
                changed = True

        _set("title", title)
        _set("description_md", description_md)
        _set("assignee_id", assignee_id)
        _set("state_id", state_id)
        _set("priority", priority)
        _set("estimate", estimate)
        if labels is not None:
            if issue.get("labels") != labels:
                issue["labels"] = labels
                changed = True
        _set("status", status)

        if not changed:
            # No success without effect: treat as conflict/no-op (real APIs vary; here use CONFLICT).
            _append_request_log("error", "CONFLICT")
            return _err("CONFLICT", "No changes to apply.")

        issue["updated_at"] = _now_iso()
        issues[idx] = issue
        _save("issues.json", issues)

        _append_request_log("success", None)
        return {"issue": issue}
    except Exception as e:
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def linear_search_issues(query=None, team_id=None, status=None, assignee_id=None, labels=None, priority=None, estimate=None, limit=None, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0204000" if __import__("os").path.isdir("./environment_mix/0204000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()
    def _log(status_s, error=None):
        for fname in ("request_logs.json", "usage.json", "audit_logs.json", "requests.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                logs = _load(fname)
                logs.append({
                    "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
                    "endpoint": "linear_search_issues",
                    "status": status_s,
                    "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
                    "latency_ms": int((time.time() - _t0) * 1000),
                    "timestamp": _now(),
                })
                _save(fname, logs)
                break

    try:
        if query is not None and not isinstance(query, str):
            _log("error", {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "query must be a string", field="query")
        if team_id is not None:
            if not isinstance(team_id, str) or not re.match(r"^team_[0-9A-HJKMNP-TV-Z]{17,}$", team_id):
                _log("error", {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "team_id is not a valid ULID", field="team_id")
        if status is not None:
            if not isinstance(status, str) or status not in ("open", "closed", "canceled", "deleted"):
                _log("error", {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "status must be one of open,closed,canceled,deleted", field="status")
        if assignee_id is not None:
            if not isinstance(assignee_id, str) or not re.match(r"^usr_[0-9A-HJKMNP-TV-Z]{17,}$", assignee_id):
                _log("error", {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "assignee_id is not a valid ULID", field="assignee_id")
        if labels is not None:
            if not isinstance(labels, list):
                _log("error", {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "labels must be an array of strings", field="labels")
            for i, lab in enumerate(labels):
                if not isinstance(lab, str) or lab.strip() == "":
                    _log("error", {"code": "VALIDATION_ERROR"})
                    return _err("VALIDATION_ERROR", "labels must be non-empty strings", field="labels", index=i)
            labels = [s.strip() for s in labels]
        if priority is not None:
            if not isinstance(priority, int) or priority not in (1, 2, 3, 4):
                _log("error", {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "priority must be one of 1,2,3,4", field="priority")
        if estimate is not None:
            if not isinstance(estimate, (int, float)):
                _log("error", {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "estimate must be a number", field="estimate")

        # limit: default 10, max 50 per business rule (even if schema says 100)
        if limit is None:
            limit = 10
        if not isinstance(limit, int):
            _log("error", {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
        if limit < 1:
            _log("error", {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be >= 1", field="limit")
        if limit > 50:
            _log("error", {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be <= 50", field="limit")

        issues = _load("issues.json")

        q = (query or "").strip().lower()
        def _match_text(it):
            if not q:
                return True
            t = (it.get("title") or "").lower()
            d = (it.get("description_md") or "").lower()
            return (q in t) or (q in d)

        def _match_labels(it):
            if labels is None or len(labels) == 0:
                return True
            iss_labels = it.get("labels") or []
