        # must have at least one of author_user_id or custom_author_name
        # business rule: if custom_author_name provided, tool uses persona mode and sets author_user_id to authenticated user unless custom_author_name is provided.
        # We'll interpret: persona mode => author_user_id should be null; otherwise attribute to authenticated user (service identity if none explicit).
        users = _load("users.json")
        if not isinstance(users, list):
            users = []

        service_user = next((u for u in users if u.get("is_service_identity") is True and u.get("status") == "active"), None)
        if service_user is None:
            # if none active, accept any service identity row
            service_user = next((u for u in users if u.get("is_service_identity") is True), None)

        if custom_author_name is None:
            # need an authenticated author; author_user_id param is accepted but backend attributes to authenticated user.
            # Since auth is ambient and we have no auth param, use service identity.
            if service_user is None:
                _log("error", error_code="UNAUTHORIZED")
                return _err("UNAUTHORIZED", "No authenticated identity available to author the comment.")
            effective_author_user_id = service_user.get("id")
        else:
            # persona mode: must not require author_user_id; stored author_user_id should be null
            effective_author_user_id = None

        # If caller explicitly provided author_user_id, validate it exists (per tool description), but do not necessarily store it
        if author_user_id is not None:
            if not any(u.get("id") == author_user_id for u in users):
                _log("error", error_code="NOT_FOUND")
                return _err("NOT_FOUND", "author_user_id does not exist.")

        if effective_author_user_id is None and custom_author_name is None:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Either author_user_id (implicitly via auth) or custom_author_name must be provided.")

        issues = _load("issues.json")
        if not isinstance(issues, list):
            issues = []
        issue = next((i for i in issues if i.get("id") == issue_id), None)
        if issue is None or issue.get("status") == "deleted":
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Issue not found.")

        # ensure issue exists and not deleted; "FORBIDDEN" not in allowed error codes; map to UNAUTHORIZED
        # (no team membership model available)
        # validate effective_author_user_id exists if set
        if effective_author_user_id is not None and not any(u.get("id") == effective_author_user_id for u in users):
            _log("error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Authenticated user not found.")

        comments = _load("comments.json")
        if not isinstance(comments, list):
            comments = []

        # enforce unique url constraint by generating an unused url
        base_url = issue.get("url") or f"https://linear.local/issue/{issue_id}"
        # id generation: cmt_ + 20 chars crockford
        crock = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

        def _new_id(prefix):
            for _ in range(50):
                s = "".join(random.choice(crock) for _ in range(20))
                cid = f"{prefix}_{s}"
                if not any(r.get("id") == cid for r in comments):
                    return cid
            return None

        cid = _new_id("cmt")
        if cid is None:
            _log("error", error_code="CONFLICT")
            return _err("CONFLICT", "Unable to allocate unique comment id.")

        # canonical URL uniqueness
        existing_urls = {c.get("url") for c in comments if isinstance(c, dict)}
        url = f"{base_url}#comment-{cid}"
        if url in existing_urls:
            # try a deterministic suffix
            for k in range(1, 200):
                u2 = f"{base_url}#comment-{cid}-{k}"
                if u2 not in existing_urls:
                    url = u2
                    break
            else:
                _log("error", error_code="CONFLICT")
                return _err("CONFLICT", "Unable to allocate unique comment url.")

        now = _now_iso()
        new_comment = {
            "id": cid,
            "issue_id": issue_id,
            "author_user_id": effective_author_user_id,
            "custom_author_name": custom_author_name,
            "custom_author_avatar_url": custom_author_avatar_url,
            "body_md": body_md,
            "url": url,
            "status": "visible",
            "created_at": now,
            "updated_at": now,
        }

        # enforce at_least_one(author_user_id, custom_author_name)
        if new_comment["author_user_id"] is None and (new_comment["custom_author_name"] is None or new_comment["custom_author_name"] == ""):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Either author_user_id or custom_author_name must be set.")

        comments.append(new_comment)

        # Update issue timestamps: last_commented_at and updated_at to comment created_at
        issue["last_commented_at"] = now
        issue["updated_at"] = now

        _save("comments.json", comments)
        _save("issues.json", issues)

        _log("ok")
        return {"comment": new_comment}
    except Exception as e:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

