    now = _now_iso()
    c["status"] = "deleted"
    c["updated_at"] = now
    _save("comments.json", comments)

    _log("ok", credential_used=actor.get("id"))
    return {"comment": c}

def linear_list_workflow_states(team_id, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0204000" if __import__("os").path.isdir("./environment_mix/0204000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        # request_logs.json is not declared in schema but required for observable dynamics.
        # Create if missing.
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                # If we cannot create logs, still proceed; but attempt to return an internal-shaped error rather than raising.
                return False
        return True

    def _append_log(endpoint, status_code, credential_used, latency_ms, meta=None):
        if not _ensure_logs():
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + os.urandom(8).hex(),
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status_code,
            "latency_ms": latency_ms,
            "ts": _now_iso(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _decode_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c:
            return "BAD"
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            obj = json.loads(s)
            return obj
        except Exception:
            return "BAD"

    def _encode_cursor(obj):
        s = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    t0 = time.time()
    endpoint = "linear_list_workflow_states"

    # -------- Validate inputs --------
    if not isinstance(team_id, str):
        latency = int((time.time() - t0) * 1000)
        _append_log(endpoint, "VALIDATION_ERROR", None, latency, {"field": "team_id"})
        return _err("VALIDATION_ERROR", "team_id must be a string", field="team_id")

    if not re.match(r"^team_[0-9A-HJKMNP-TV-Z]{17,}$", team_id):
        latency = int((time.time() - t0) * 1000)
        _append_log(endpoint, "VALIDATION_ERROR", None, latency, {"field": "team_id"})
        return _err("VALIDATION_ERROR", "team_id does not match required pattern", field="team_id")

    if status is None:
        status = "active"
    if not isinstance(status, str):
        latency = int((time.time() - t0) * 1000)
        _append_log(endpoint, "VALIDATION_ERROR", None, latency, {"field": "status"})
        return _err("VALIDATION_ERROR", "status must be a string", field="status")
    if status not in ("active", "hidden", "all"):
        latency = int((time.time() - t0) * 1000)
        _append_log(endpoint, "VALIDATION_ERROR", None, latency, {"field": "status"})
        return _err("VALIDATION_ERROR", "status must be one of: active, hidden, all", field="status")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        latency = int((time.time() - t0) * 1000)
        _append_log(endpoint, "VALIDATION_ERROR", None, latency, {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit < 1 or limit > 100:
        latency = int((time.time() - t0) * 1000)
        _append_log(endpoint, "VALIDATION_ERROR", None, latency, {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")

    cur = _decode_cursor(cursor)
    if cur == "BAD":
        latency = int((time.time() - t0) * 1000)
        _append_log(endpoint, "VALIDATION_ERROR", None, latency, {"field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    # -------- Ambient auth resolution --------
    # No explicit credential parameter. Choose a service identity user if available.
    users = _load("users.json")
    service_user = None
    if isinstance(users, list):
        for u in users:
            if isinstance(u, dict) and u.get("is_service_identity") is True and u.get("status") == "active":
                service_user = u
                break
    # If no users exist at all, treat as unauthorized (can't resolve identity).
    if service_user is None:
        latency = int((time.time() - t0) * 1000)
        _append_log(endpoint, "UNAUTHORIZED", None, latency, {"reason": "no_service_identity"})
        return _err("UNAUTHORIZED", "No authenticated identity available to service the request")

    credential_used = service_user.get("id")

    # -------- Team existence / access control --------
    teams = _load("teams.json")
    team_row = None
    if isinstance(teams, list):
        for t in teams:
            if isinstance(t, dict) and t.get("id") == team_id:
                team_row = t
                break
    if team_row is None:
        latency = int((time.time() - t0) * 1000)
        _append_log(endpoint, "NOT_FOUND", credential_used, latency, {"team_id": team_id})
        return _err("NOT_FOUND", "Team not found", team_id=team_id)

    # "FORBIDDEN if you are not allowed to view the team’s workflow."
    # No membership model exists in schema; with ambient auth and no ACL data, treat as allowed.
    # If team is archived, workflow can still be viewed; not forbidden.

    # -------- Query + pagination --------
    states = _load("workflow_states.json")
    if not isinstance(states, list):
        states = []

    filtered = []
    for s in states:
        if not isinstance(s, dict):
            continue
        if s.get("team_id") != team_id:
            continue
        st = s.get("status")
        if status == "active":
            if st != "active":
                continue
        elif status == "hidden":
            if st != "hidden":
                continue
        elif status == "all":
            if st not in ("active", "hidden"):
                continue
        filtered.append(s)

    # order by position asc, then created_at asc, then id
    def _key(r):
        pos = r.get("position")
        try:
            pos = int(pos)
        except Exception:
            pos = 0
        ca = r.get("created_at") or ""
        return (pos, ca, r.get("id") or "")
    filtered.sort(key=_key)

    start = 0
    if cur is not None:
        # cursor shape: {"team_id": "...", "offset": N, "status": "..."}
        if not isinstance(cur, dict):
            latency = int((time.time() - t0) * 1000)
            _append_log(endpoint, "VALIDATION_ERROR", credential_used, latency, {"field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        if cur.get("team_id") != team_id:
            latency = int((time.time() - t0) * 1000)
            _append_log(endpoint, "VALIDATION_ERROR", credential_used, latency, {"field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor does not match team_id", field="cursor")
        if cur.get("status") != status:
            latency = int((time.time() - t0) * 1000)
            _append_log(endpoint, "VALIDATION_ERROR", credential_used, latency, {"field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor does not match status filter", field="cursor")
        off = cur.get("offset")
        if not isinstance(off, int) or off < 0:
            latency = int((time.time() - t0) * 1000)
            _append_log(endpoint, "VALIDATION_ERROR", credential_used, latency, {"field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor offset is invalid", field="cursor")
        start = off
        if start > len(filtered):
            start = len(filtered)

    total = len(filtered)
    page = filtered[start:start + limit]
    next_cursor = None
    has_more = (start + limit) < total
    if has_more:
        next_cursor = _encode_cursor({"team_id": team_id, "status": status, "offset": start + limit})

    latency = int((time.time() - t0) * 1000)
    _append_log(endpoint, "OK", credential_used, latency, {"team_id": team_id, "returned": len(page), "total": total})

    return {
        "workflow_states": page,
        "meta": {
            "team_id": team_id,
            "status": status,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total
        }
    }
